normalization_rows.source:
projection CustomerProjection {
  source: OrderCreated
  target: CustomerView
}

consumer OrdersConsumer {
  topic: Orders
  source: OrderCreated
}

entity Customer {
  field id: UUID
  field email: String
}

index ByEmail {
  fields: [email asc, tenantId desc]
  unique: true
}

schedule_lease CleanupLease {
  schedule: CleanupNightly
  singleton: true
  lease: 30s
}

sync_outbox MobileSyncPolicy {
  changes: Customer
  delivery: outbox
}

multi_source_projection:
projection OrderSummary {
  source: Order
  source: Payment
  target: OrderView
}

representative_families.source:
service Billing {
  api: BillingApi
  resource: Postgres
}

workflow Reconcile {
  step: load
  step: compare
}

deployment Prod {
  target: Kubernetes
  resource: Billing
}

legacy_rejections:
projection CustomerProjection from [OrderCreated] into CustomerView {
}
client BillingClient for BillingService {
}
consumer OrdersConsumer on Orders from OrderCreated {
}
sync MobileSync {
  changes MobileChanges via outbox SyncOutbox
}
